1	import { test, expect } from '@playwright/test';
2	import { loginAsAdmin } from '../fixtures/auth';
3	import { SettingsPage } from '../pages/settings';
4	
5	/**
6	 * Imagify Settings page tests.
7	 *
8	 * Without a valid API key only the account section (API key input + save
9	 * button) is visible. The Lossless, WebP/AVIF, and Library sections are
10	 * hidden and require IMAGIFY_TESTS_API_KEY to be tested.
11	 */
12	test.describe( 'Imagify settings', () => {
13		test.beforeEach( async ( { page } ) => {
14			await loginAsAdmin( page );
15		} );
16	
17		test( 'Settings page renders without fatal errors', async ( { page } ) => {
18			const settings = new SettingsPage( page );
19			await settings.goto();
20	
21			await settings.expectNoFatalError();
22			await expect( page ).toHaveURL( /page=imagify/ );
23		} );
24	
25		test( 'Settings page has a save button', async ( { page } ) => {
26			const settings = new SettingsPage( page );
27			await settings.goto();
28	
29			await expect( settings.saveButton ).toBeVisible();
30		} );
31	
32		test( 'Lossless compression option is present (requires API key)', async ( { page } ) => {
33			test.skip( ! process.env.IMAGIFY_TESTS_API_KEY, 'IMAGIFY_TESTS_API_KEY not set — settings sections hidden without valid key' );
34	
35			const settings = new SettingsPage( page );
36			await settings.goto();
37	
38			// Imagify uses a "Lossless compression" checkbox, not Normal/Aggressive/Ultra labels.
39			const losslessLabel = page.locator( 'label' ).filter( { hasText: /lossless/i } );
40			await expect( losslessLabel ).toBeVisible();
41		} );
42	
43		test( 'WebP/AVIF next-gen format toggles are present (requires API key)', async ( { page } ) => {
44			test.skip( ! process.env.IMAGIFY_TESTS_API_KEY, 'IMAGIFY_TESTS_API_KEY not set — settings sections hidden without valid key' );
45	
46			const settings = new SettingsPage( page );
47			await settings.goto();
48	
49			// The format radio buttons use label[for="imagify_optimization_format_webp"] etc.
50			const webpLabel = page.locator( 'label[for="imagify_optimization_format_webp"]' );
51			await expect( webpLabel ).toBeVisible();
52		} );
53	
54		test( 'Saving settings without changing values succeeds', async ( { page } ) => {
55			const settings = new SettingsPage( page );
56			await settings.goto();
57	
58			await settings.saveButton.click();
59			await page.waitForLoadState( 'networkidle' );
60	
61			await settings.expectNoFatalError();
62			// After save the page should redirect back to the settings page.
63			await expect( page ).toHaveURL( /page=imagify/ );
64		} );
65	} );
